def read_number(n: int) -> str:
    if n == 0:
        return '영'

    digits_map = ['영', '일', '이', '삼', '사', '오', '육', '칠', '팔', '구']
    place_names = ['', '십', '백', '천']

    def read_four_digits(num):
        """Read a group of up to 4 digits (0-9999)"""
        if num == 0:
            return ''

        result = ''
        # Process from highest to lowest place value within the group
        # positions: 0=ones, 1=tens, 2=hundreds, 3=thousands
        for pos in range(3, -1, -1):
            digit = (num // (10 ** pos)) % 10
            if digit == 0:
                continue

            # Don't read '1' before 천, 백, 십
            if digit == 1 and pos > 0:
                result += place_names[pos]
            else:
                result += digits_map[digit] + place_names[pos]

        return result

    # Split into groups of 4 digits from right to left
    ones_group = n % 10000
    man_group = (n // 10000) % 10000
    eok_group = (n // 100000000) % 10000

    result = ''

    # Process 억 (hundred millions)
    if eok_group > 0:
        result += read_four_digits(eok_group) + '억'

    # Process 만 (ten thousands)
    if man_group > 0:
        if man_group == 1:
            result += '만'
        else:
            result += read_four_digits(man_group) + '만'

    # Process ones group
    if ones_group > 0:
        result += read_four_digits(ones_group)

    return result
